  /// Adds a fallback Roboto font to the bundled assets.
  ///
  /// This registers a `Roboto` entry in `FontManifest.json` and copies the
  /// Roboto font shipped with the Flutter engine into the output assets
  /// directory. This is used when CanvasKit is bundled locally so that text
  /// can be rendered without fetching fonts from the network.
  void _bundleLocalFallbackFont(Environment environment) {
    final FileSystem fileSystem = environment.fileSystem;
    final Directory assetsDirectory = environment.outputDir.childDirectory('assets');

    // Add a Roboto entry to the FontManifest.json, avoiding duplicates.
    final File fontManifestFile = assetsDirectory.childFile(kFontManifestJson);
    final fontManifest = <Object?>[];
    if (fontManifestFile.existsSync()) {
      final Object? decoded = jsonDecode(fontManifestFile.readAsStringSync());
      if (decoded is List) {
        fontManifest.addAll(decoded);
      }
    }

    final bool hasRoboto = fontManifest.any(
      (Object? entry) => entry is Map && entry['family'] == 'Roboto',
    );
    if (!hasRoboto) {
      fontManifest.add(<String, Object?>{
        'family': 'Roboto',
        'fonts': <Object?>[
          <String, String>{'asset': 'fonts/fallback/Roboto-Regular.ttf'},
        ],
      });
      fontManifestFile.createSync(recursive: true);
      fontManifestFile.writeAsStringSync(jsonEncode(fontManifest));
    }

    // Copy the Roboto font from the engine source tree into the output assets.
    final File robotoSource = fileSystem.file(
      fileSystem.path.join(
        Cache.flutterRoot!,
        'engine',
        'src',
        'flutter',
        'txt',
        'third_party',
        'fonts',
        'Roboto-Regular.ttf',
      ),
    );
    final File robotoDestination = assetsDirectory
        .childDirectory('fonts')
        .childDirectory('fallback')
        .childFile('Roboto-Regular.ttf');
    robotoDestination.parent.createSync(recursive: true);
    robotoSource.copySync(robotoDestination.path);
  }
